namespace aiprovider_modelled;

/**
 * A provider that lists its models, the way core's providers and those built like them do.
 *
 * Its helper returns the models themselves rather than their class names, which is the
 * other of the two shapes the router reads, so that both are exercised.
 *
 * @package    local_airouter
 * @copyright  2026 UDAGAWA Mitsuru
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class provider extends \core_ai\provider {
    #[\Override]
    public static function get_action_list(): array {
        return [
            \core_ai\aiactions\generate_text::class,
            \core_ai\aiactions\summarise_text::class,
            \core_ai\aiactions\generate_image::class,
        ];
    }

    #[\Override]
    public function is_provider_configured(): bool {
        return true;
    }

    #[\Override]
    public function get_name(): string {
        return 'aiprovider_modelled';
    }
}
